-- SQL Server SQL_Latin1_General_CP1_CI_AS char/varchar equality over CP1252, defined as identity and programs-sites define it.
CREATE COLLATION IF NOT EXISTS people.legacy_char_ci (provider = icu, locale = 'und', deterministic = false, rules = E'&a=A&b=B&c=C&d=D&e=E&f=F&g=G&h=H&i=I&j=J&k=K&l=L&m=M&n=N&o=O&p=P&q=Q&r=R&s=S&t=T&u=U&v=V&w=W&x=X&y=Y&z=Z&\u00E0=\u00C0&\u00E1=\u00C1&\u00E2=\u00C2&\u00E3=\u00C3&\u00E4=\u00C4&\u00E5=\u00C5&\u00E6=\u00C6&\u00E7=\u00C7&\u00E8=\u00C8&\u00E9=\u00C9&\u00EA=\u00CA&\u00EB=\u00CB&\u00EC=\u00CC&\u00ED=\u00CD&\u00EE=\u00CE&\u00EF=\u00CF&\u00F0=\u00D0&\u00F1=\u00D1&\u00F2=\u00D2&\u00F3=\u00D3&\u00F4=\u00D4&\u00F5=\u00D5&\u00F6=\u00D6&\u00F8=\u00D8&\u00F9=\u00D9&\u00FA=\u00DA&\u00FB=\u00DB&\u00FC=\u00DC&\u00FD=\u00DD&\u00FE=\u00DE&\u0161<<<\u0160&\u017E<<<\u017D&\u00FF<<<\u0178&\'\u0009\'<\u0001<\u0002<\u0003<\u0004<\u0005<\u0006<\u0007<\u0008<\u000E<\u000F<\u0010<\u0011<\u0012<\u0013<\u0014<\u0015<\u0016<\u0017<\u0018<\u0019<\u001A<\u001B<\u001C<\u001D<\u001E<\u001F<\u007F<\u00AD');
-- Set lookups compare (extendsetid COLLATE legacy_char_ci), which is leakproof and so indexable under forced RLS; lower() is not.
CREATE INDEX IF NOT EXISTS extend_attribute_tenant_extendsetid_ci_idx ON people.extend_attribute (tenant_id, extendsetid COLLATE people.legacy_char_ci);
